import React, { useState } from "react";
import "../checkout.css";
import { useCart } from "../components/CartContext";

const Checkout = ({ onClose }) => {
  const { cartItems } = useCart();
  const [address, setAddress] = useState("");
  const [paymentMethod, setPaymentMethod] = useState("card");
  const [orderPlaced, setOrderPlaced] = useState(false);

  const total = cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0);

  const estimatedDelivery = (() => {
    const date = new Date();
    date.setDate(date.getDate() + 3);
    return date.toDateString();
  })();

  const handlePlaceOrder = () => {
    setOrderPlaced(true);
    setTimeout(() => {
      setOrderPlaced(false);
      if (onClose) onClose();
    }, 1800);
  };

  return (
    <div className="checkout-container" style={{position: 'relative', minWidth: 320, maxWidth: 480, width: '100%'}}>
      {onClose && (
        <button
          onClick={onClose}
          style={{position: 'absolute', top: 10, right: 15, fontSize: 22, background: 'none', border: 'none', cursor: 'pointer', color: '#888'}}
          aria-label="Close"
        >
          &times;
        </button>
      )}
      <h2 style={{textAlign: 'center', color: 'var(--color-primary)', marginBottom: 18}}>Checkout</h2>

      {/* Order Summary at the top */}
      <div className="section">
        <h3>Order Summary</h3>
        <ul style={{marginBottom: 8}}>
          {cartItems.length === 0 ? (
            <li style={{color: '#d32f2f'}}>No items in cart.</li>
          ) : (
            cartItems.map((item) => (
              <li key={item._id} style={{marginBottom: 4, display: 'flex', justifyContent: 'space-between', alignItems: 'center'}}>
                <span>
                  <strong>{item.name}</strong> x {item.quantity}
                </span>
                <span>₹{item.price * item.quantity}</span>
              </li>
            ))
          )}
        </ul>
      </div>

      {/* Shipping Address next */}
      <div className="section">
        <h3>Shipping Address</h3>
        <textarea
          value={address}
          onChange={(e) => setAddress(e.target.value)}
          placeholder="Enter full shipping address"
          style={{resize: 'vertical', border: '1.5px solid var(--color-border)', borderRadius: 8, minHeight: 60, fontSize: 15}}
        />
      </div>

      {/* Payment Method next */}
      <div className="section">
        <h3>Payment Method</h3>
        <div style={{display: 'flex', gap: 18, marginBottom: 8}}>
          {["card", "upi", "cod"].map((method) => (
            <label key={method} style={{fontWeight: 500, fontSize: 15, cursor: 'pointer'}}>
              <input
                type="radio"
                name="payment"
                value={method}
                checked={paymentMethod === method}
                onChange={() => setPaymentMethod(method)}
                style={{marginRight: 7}}
              />
              {method.toUpperCase()}
            </label>
          ))}
        </div>
      </div>

      {/* Total and Estimated Delivery at the bottom */}
      <div className="section" style={{marginBottom: 0}}>
        <div style={{display: 'flex', justifyContent: 'space-between', fontWeight: 600, fontSize: 17, color: 'var(--color-primary)', marginBottom: 8}}>
          <span>Total:</span>
          <span>₹{total}</span>
        </div>
        <div style={{marginBottom: 10}}>
          <h4 style={{margin: 0, fontSize: 15, color: '#555'}}>Estimated Delivery</h4>
          <p style={{margin: 0, color: '#555', fontSize: 15}}>{estimatedDelivery}</p>
        </div>
        <button
          className="place-order-btn"
          onClick={handlePlaceOrder}
          disabled={cartItems.length === 0 || !address.trim() || orderPlaced}
          style={{marginTop: 10, opacity: orderPlaced ? 0.7 : 1}}
        >
          {orderPlaced ? 'Order Placed!' : 'Place Order'}
        </button>
      </div>
    </div>
  );
};

export default Checkout;
